const payload = $json || {};

const sourceName = payload.source_name || payload.source || payload.workflowName || payload?.workflow?.name || 'Unknown Source';
const sourceKey = payload.source_key || null;
const sourcePlatform = payload.source_platform || null;
const signalOrigin = payload.signal_origin || null;
const eventType = payload.event_type || (payload.execution ? 'WORKFLOW_ERROR' : 'ERROR');
const errorMessage = payload.error || payload.message || payload?.execution?.error?.message || 'No error details provided.';
const targetUrl = payload.target_url || payload.url || '-';
const workflowName = payload.workflow_name || payload.workflowName || payload?.workflow?.name || null;
const nodeName = payload.node_name || payload.nodeName || payload?.node?.name || null;
const executionId = payload.execution_id || payload.executionId || payload?.execution?.id || null;
const nowIso = new Date().toISOString();
const consoleUrl = $env.N8N_EDITOR_BASE_URL || 'http://localhost:5678';

const TIMEZONE = 'Asia/Shanghai';

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function formatShortDateTime(date, timezone) {
  try {
    const d = new Date(date);
    const datePart = new Intl.DateTimeFormat('en-US', {
      month: 'numeric',
      day: 'numeric',
      timeZone: timezone,
    }).format(d);
    const timePart = new Intl.DateTimeFormat('zh-CN', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
      timeZone: timezone,
    }).format(d);
    return `${datePart} ${timePart}`;
  } catch {
    return '';
  }
}

// Only what this alert actually carries: both callers fill different halves,
// so a fixed field list would render half the rows as dashes.
const metaParts = [];
for (const candidate of [
  sourceName,
  payload.source,
  sourceKey,
  sourcePlatform,
  signalOrigin,
  workflowName,
  nodeName,
  executionId ? '#' + executionId : null,
]) {
  const value = String(candidate ?? '').trim();
  if (!value || value === '-' || value === 'Unknown Source') continue;
  if (!metaParts.includes(value)) metaParts.push(value);
}

const DOT = '<span style="margin: 0 6px; color: #999;">&middot;</span>';

let html = '';
html += '<div style="font-family: \'Helvetica Neue\', Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; color: #000000;">';

html += '<div style="padding-bottom: 16px; border-bottom: 2px solid #000000; margin-bottom: 24px;">';
html += '<h1 style="margin: 0; font-size: 24px; font-weight: 700; letter-spacing: -0.5px; color: #000000;">System Alert</h1>';
html += '<p style="margin: 4px 0 0 0; color: #000000; font-size: 14px; font-weight: 620;">' + escapeHtml(eventType) + ' | ' + escapeHtml(formatShortDateTime(nowIso, TIMEZONE)) + '</p>';
html += '</div>';

html += '<div style="margin-bottom: 28px;">';
if (metaParts.length) {
  html += '<div style="font-size: 12px; color: #444444; margin-bottom: 4px; font-weight: 650;">';
  html += metaParts.map(escapeHtml).join(DOT);
  html += '</div>';
}
html += '<h3 style="margin: 0 0 6px 0; font-size: 18px; line-height: 1.4; font-weight: 650;">' + escapeHtml(errorMessage) + '</h3>';
if (targetUrl && targetUrl !== '-') {
  html += '<p style="margin: 0; font-size: 14px; line-height: 1.6; font-weight: 650; word-break: break-all;">';
  html += '<a href="' + escapeHtml(targetUrl) + '" style="text-decoration: none; color: #1a73e8;">' + escapeHtml(targetUrl) + '</a>';
  html += '</p>';
}
html += '</div>';

html += '<div style="padding-top: 30px; border-top: 1px solid #dfe1e5; text-align: center;">';
html += '<a href="' + escapeHtml(consoleUrl) + '" style="display: inline-block; width: 160px; background-color: #1a73e8; color: #ffffff; padding: 12px 0; text-align: center; border-radius: 4px; text-decoration: none; font-size: 14px; font-weight: 700;">Open n8n Console</a>';
html += '</div>';
html += '</div>';

return [{
  json: {
    event_type: eventType,
    source: sourceName,
    source_key: sourceKey,
    source_name: payload.source_name || sourceName,
    source_platform: sourcePlatform,
    signal_origin: signalOrigin,
    target_url: targetUrl,
    error: errorMessage,
    message: errorMessage,
    workflow_name: workflowName,
    node_name: nodeName,
    execution_id: executionId,
    alert_time: nowIso,
    console_url: consoleUrl,
    email_body: html
  }
}];
